export interface StockLevelDto {
  productId: string;
  name: string;
  onHand: number;
  reserved: number;
  available: number;
}

export function toOrderDto(order: Order): OrderDto {
  return {
    id: order.id,
    state: order.state,
    lines: order.lines.map((line) => ({ productId: line.productId, quantity: line.quantity })),
  };
}

